/// updates the table; nothing hand-written to keep in sync).
///
/// Scopes in table order: `composer`, `run` (run & queue), `picker`, `prompt`.
const kTuiKeybindings = <TuiKeybinding>[
  // ── Composer / editor ────────────────────────────────────────────────
