  static final _tableRowRe = RegExp(r'^\s*\|.*\|\s*$');
  static final _tableSeparatorCellRe = RegExp(r'^:?-+:?$');
  static final _ansiRe = RegExp(r'\x1b\[[0-9;]*m');
