  'opt': 'alt',
  'cmd': 'super',
  'command': 'super',
  'pgdn': 'pgdown',
};

Map<String, String> _modifierLabels(bool darwin) => {
      'ctrl': 'Ctrl',
      'alt': darwin ? 'Option' : 'Alt',
      'shift': 'Shift',
      'meta': 'Meta',
      'super': darwin ? 'Cmd' : 'Super',
