  'esc': 'Esc',
  'tab': 'Tab',
  'space': 'Space',
  'backspace': 'Backspace',
  'delete': 'Delete',
  'home': 'Home',
  'end': 'End',
  'pgup': 'PgUp',
  'pgdown': 'PgDn',
  'up': '↑',
  'down': '↓',
  'left': '←',
  'right': '→',
};

String _titleKey(String k) =>
    k.length <= 1 ? k.toUpperCase() : k[0].toUpperCase() + k.substring(1);

