  'space': 'Space',
  'backspace': 'Backspace',
  'delete': 'Delete',
  'home': 'Home',
  'end': 'End',
  'pgup': 'PgUp',
  'pgdown': 'PgDn',
  'up': '↑',
  'down': '↓',
  'left': '←',
  'right': '→',
};

String _titleKey(String k) =>
